// Build the approval-card instruction for OpenFang approval-handler agent.
// The card has the proposal preview + approval-token; the user replies
// APPROVE or REJECT, OpenFang's brain-gateway routes the response back
// to marketing's /api/reply_proposals/{id}/approve endpoint.

const webhook = $('Webhook (reply_proposal_status_changed)').first().json.data;
const proposal = $('Get proposal status').first().json.data || {};

// Operator chat_id placeholder - set on workflow import.
// For multi-operator setups this would come from a `approval_recipients` config.
const recipient = 'REPLACE_WITH_OPERATOR_CHAT_ID';
const channel = webhook.approval_channel || 'telegram';

return [{
  json: {
    instruction: 'MARKETING-APPROVAL-V1. Send approval-card.\n\n' + JSON.stringify({
      action: 'approval_request',
      args: {
        proposal_id: webhook.proposal_id,
        channel: channel,
        recipient: recipient,
        preview: {
          to_email: proposal.draft_to_email,
          subject: proposal.draft_subject,
          body_preview: '(see curator-UI for full body)'
        },
        // Note: the actual approval_token is NOT carried through n8n.
        // It was returned by curator.request_approval and stored
        // securely (operator copies it to a vault). The user that
        // approves provides the token when calling /approve.
        approval_token_hint: 'use the token from curator-UI',
        callback_url: 'http://127.0.0.1:5510/api/reply_proposals/' + webhook.proposal_id + '/approve'
      }
    })
  }
}];
